from decimal import Decimal, InvalidOperation

def process_payments(requests):
    if not isinstance(requests, list):
        raise ValueError('requests must be a list')
    applied = []
    duplicates = []
    conflicts = []
    balances_by_pair = {}
    first_by_key = {}
    for request in requests:
        if not isinstance(request, dict):
            raise ValueError('request must be a dict')
        for field in ('key', 'account', 'currency', 'amount', 'reference'):
            if field not in request:
                raise ValueError('missing field: ' + field)
        key = request['key']
        account = request['account']
        currency_raw = request['currency']
        amount_raw = request['amount']
        reference = request['reference']
        if not isinstance(key, str) or key == '':
            raise ValueError('invalid key')
        if not isinstance(account, str) or account == '':
            raise ValueError('invalid account')
        if not isinstance(currency_raw, str) or len(currency_raw) != 3 or not all(('A' <= ch <= 'Z') or ('a' <= ch <= 'z') for ch in currency_raw):
            raise ValueError('invalid currency')
        currency = currency_raw.upper()
        if not isinstance(amount_raw, str):
            raise ValueError('invalid amount')
        try:
            amount = Decimal(amount_raw)
        except (InvalidOperation, ValueError):
            raise ValueError('invalid amount') from None
        if not amount.is_finite() or amount <= 0:
            raise ValueError('invalid amount')
        if amount.as_tuple().exponent < -2:
            raise ValueError('invalid amount')
        if not isinstance(reference, str):
            raise ValueError('invalid reference')
        if key not in first_by_key:
            first_by_key[key] = (account, currency, amount, reference)
            amount_d2 = amount.quantize(Decimal('0.01'))
            balance = balances_by_pair.get((account, currency), Decimal('0.00')) + amount_d2
            balance = balance.quantize(Decimal('0.01'))
            balances_by_pair[(account, currency)] = balance
            applied.append({'key': key, 'account': account, 'currency': currency, 'amount': amount_d2, 'balance_after': balance})
        elif (account, currency, amount, reference) == first_by_key[key]:
            duplicates.append(key)
        else:
            conflicts.append({'key': key, 'reason': 'payload differs from first occurrence'})
    balances_text = {}
    for (account, currency), balance in balances_by_pair.items():
        balances_text[account + ':' + currency] = balance
    balances = dict(sorted(balances_text.items()))
    return {'applied': applied, 'duplicates': duplicates, 'conflicts': conflicts, 'balances': balances}

