from datetime import date, datetime, time, timedelta, timezone
from zoneinfo import ZoneInfo

def _is_ascii_digits(text):
    return text != '' and all('0' <= ch <= '9' for ch in text)

def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    if len(value) != 10 or value[4] != '-' or value[7] != '-':
        raise ValueError('invalid date')
    if not _is_ascii_digits(value[0:4]) or not _is_ascii_digits(value[5:7]) or not _is_ascii_digits(value[8:10]):
        raise ValueError('invalid date')
    try:
        return date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise ValueError('invalid date') from None

def _parse_holidays(holidays):
    if isinstance(holidays, (str, bytes)):
        raise ValueError('invalid holidays')
    try:
        entries = list(holidays)
    except TypeError:
        raise ValueError('invalid holidays') from None
    parsed = set()
    for entry in entries:
        parsed.add(_parse_date(entry))
    return parsed

def is_madrid_business_day(date_str, holidays=()):
    parsed_date = _parse_date(date_str)
    holiday_set = _parse_holidays(holidays)
    return parsed_date.weekday() < 5 and parsed_date not in holiday_set

def payment_value_date(submitted, holidays=()):
    holiday_set = _parse_holidays(holidays)
    if not isinstance(submitted, str):
        raise ValueError('invalid submitted datetime')
    if len(submitted) not in (16, 19):
        raise ValueError('invalid submitted datetime')
    if submitted[4] != '-' or submitted[7] != '-' or submitted[10] != 'T' or submitted[13] != ':':
        raise ValueError('invalid submitted datetime')
    if len(submitted) == 19 and submitted[16] != ':':
        raise ValueError('invalid submitted datetime')
    submitted_date = _parse_date(submitted[0:10])
    hour_text = submitted[11:13]
    minute_text = submitted[14:16]
    second_text = submitted[17:19] if len(submitted) == 19 else '00'
    if not _is_ascii_digits(hour_text) or not _is_ascii_digits(minute_text) or not _is_ascii_digits(second_text):
        raise ValueError('invalid submitted datetime')
    try:
        local_dt = datetime(submitted_date.year, submitted_date.month, submitted_date.day, int(hour_text), int(minute_text), int(second_text))
    except ValueError:
        raise ValueError('invalid submitted datetime') from None
    madrid_tz = ZoneInfo('Europe/Madrid')
    aware_dt = local_dt.replace(tzinfo=madrid_tz)
    round_trip = aware_dt.astimezone(timezone.utc).astimezone(madrid_tz)
    if round_trip.replace(tzinfo=None) != local_dt:
        raise ValueError('nonexistent local time')
    if submitted_date.weekday() < 5 and submitted_date not in holiday_set and local_dt.time() < time(17, 0):
        return submitted_date.isoformat()
    candidate = submitted_date + timedelta(days=1)
    while candidate.weekday() >= 5 or candidate in holiday_set:
        candidate = candidate + timedelta(days=1)
    return candidate.isoformat()

