from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

def _parse_decimal(value):
    if not isinstance(value, str):
        raise ValueError('invalid decimal')
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid decimal') from None
    if not parsed.is_finite():
        raise ValueError('invalid decimal')
    return parsed

def percent_change(old, new):
    old_value = _parse_decimal(old)
    new_value = _parse_decimal(new)
    if old_value == 0:
        if new_value == 0:
            return Decimal('0.00')
        return None
    with localcontext() as ctx:
        ctx.prec = 1000
        result = (new_value - old_value) / abs(old_value) * Decimal('100')
        return result.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

def apply_percent_change(old, percent):
    old_value = _parse_decimal(old)
    percent_value = _parse_decimal(percent)
    with localcontext() as ctx:
        ctx.prec = 1000
        result = old_value * (Decimal('1') + percent_value / Decimal('100'))
        return result.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
